from review import card,save,DATE
i='TCS-3617';_,c=card(i);refs=c['references'];refs[0]['locator']='Definition 5 and Theorem 6; Section 3.4, balanced-case size comparison and restricted nice-pair construction.'
refs += [dict(id='full',title='Approximate Counting of k-Paths: Simpler, Deterministic, and in Polynomial Space',authors='Andreas Björklund; Daniel Lokshtanov; Saket Saurabh; Meirav Zehavi',year=2021,url='https://doi.org/10.1145/3461477',pdf_url='https://sites.cs.ucsb.edu/~daniello/papers/mainCountingTALGSubgraphs.pdf',locator='TALG 17(3), article 26; author-hosted full manuscript, Definition 3.1, Theorem 3.1 and proof, Section 5.1. The same general deterministic construction question remains; nice pairs are a restriction.')]
issue='The source explicitly contrasts balanced-case sizes 4^{k+o(k)} and 2^{k+o(k)}, but leaves dependence on universe size n and accuracy δ suppressed in that sentence. It does not fix the permitted deterministic construction time, enumeration delay or workspace for the general family. The joint asymptotic regime must be stated: taking δ fixed, inverse-polynomial or exponentially small can change whether overhead is subexponential in k. No arbitrary bound such as exactly matching the randomized output-linear time is imposed here.'
notes=['Recovered full coverage and multiplicative near-uniform counts, including the supplied positive correction factor.','Restored the balanced-case 2^{k+o(k)} target and the random family-size formula.','Distinguished families for all disjoint pairs from the deterministic nice-pair relaxation.','Preserved suppressed n/δ dependence and unspecified deterministic resources; checked the 2021 full article and later searches.']
save(i,dict(title='Small deterministic parsimonious universal families',formal='Can small δ-parsimonious universal families be constructed deterministically, matching the desired leading exponential dependence on k=p+q? In the balanced case p=q=k/2, the source specifically seeks size 2^{k+o(k)} in place of the cited deterministic 4^{k+o(k)} scale. The family must give nearly the same positive number of separations for every disjoint pair of a p-set and a q-set, and supply its correction factor. The source suppresses dependence on n and δ in this comparison and leaves the deterministic resource target implicit, so the complete joint-parameter construction claim remains to be specified.',definitions='Let U=[n]={1,…,n}, with positive integers p,q and k=p+q≤n, and let 0<δ<1 be an accuracy parameter. For a finite indexed collection F=(F₁,…,Fₜ) of subsets of U, define N_F(A,B)=|{j∈[t]: A⊆Fⱼ and B∩Fⱼ=∅}|. The collection is δ-parsimonious if a single positive correction factor T satisfies (1−δ)T≤N_F(A,B)≤(1+δ)T for every pair of disjoint sets A,B⊆U with |A|=p and |B|=q. In particular every such pair is separated at least once, since its integer count is strictly positive. T is the same for all pairs and must be provided with the family. Counting is by entries, as in the source’s independently generated indexed family; repeated entries cannot simply be discarded while preserving these counts. An entry may be represented by its n-bit membership vector. The deterministic construction task receives n,p,q and a finite representation of δ, and must produce the family and a usable representation of T with no failure probability. The number of entries, total construction time, delay between emitted entries and working memory are separate resources. For p=q=k/2, k is even and tends to infinity; o(k) denotes a function whose ratio to k tends to zero, once the dependence of n and δ on k has been specified. An ordinary universal family guarantees only N_F(A,B)≥1 and allows unbounded variation in those counts. A construction that works only on selected pairs does not satisfy this definition for all pairs.',question_type='yes_no',answer_criterion='Under a fully specified joint parameter regime and deterministic resource bounds, construct a family and correction factor meeting the near-uniform separation inequalities for every disjoint pair and the stated size bound, or prove that this construction requirement is impossible. An ordinary universal family, a randomized construction, or a family satisfying the inequalities only for the paper’s selected nice pairs does not settle the unrestricted target. Suppressed universe-size/accuracy dependence and deterministic resource bounds must be fixed before this can serve as a complete benchmark proposition.',context_blocks=[dict(title='Parsimony controls counting distortion',text='Coverage alone is enough to locate a witness, but counting through many separations can count different witnesses different numbers of times. A common correction factor with relative error δ limits that distortion.',citation='primary'),dict(title='Small families exist with random construction',text='The source constructs an indexed family of size O((k^k/(p^p q^q))k log n·δ⁻²) in O(tn) time for t entries, with success probability at least 1−n^{−100k}. In the balanced case the leading ratio is 2^k. This includes n and δ factors omitted from the later shorthand comparison.',citation='primary'),dict(title='The deterministic counting algorithm uses a relaxation',text='The full article repeats the desired balanced-case size improvement, then defines a family for nice pairs satisfying additional compatibility conditions. Its deterministic path-counting theorem uses that relaxation and does not assert a general parsimonious universal-family construction.',citation='full')],why='Would make uniform multiplicity control available as an explicit combinatorial tool for deterministic approximate counting, beyond the specially structured pairs used in the existing path algorithm.',references=refs,progress=[dict(date='2019',text='Randomized small families and deterministic restricted families are established; the general small deterministic construction is left open.',citation='primary'),dict(date='2021',text='The TALG full article retains the unrestricted question and develops the nice-pair relaxation in detail.',citation='full')],status='uncertain',status_note='Read the exact family definition, random construction and its indexing convention, and the deterministic section in both the conference and full versions. Subsequent searches through 12 September 2026 did not locate a general construction meeting the intended size scale. The exact n/δ regime and deterministic resource bounds remain unspecified in the extracted question.',model_self_contained=False,requires_context=True,statement_review=dict(status='needs_specification',reviewed_on=DATE,notes=notes,remaining_issue=issue),review_note=issue,importance=dict(score=c['importance']['score'],method='editorial',reason='An explicit combinatorial construction question that separates witness coverage from the multiplicity control needed for approximate counting. Existing score retained.',assessed_on=DATE),working_summary=dict(sentences=['A universal family separates every disjoint p-set and q-set in an n-element universe.','Parsimony additionally requires approximately the same number of family entries to separate each pair.','The desired deterministic size has leading scale 2^k for balanced pairs, where k=p+q.','The source supplies a random construction and a deterministic relaxation for selected pairs, rather than the general construction.','The suppressed universe-size and accuracy dependence, along with deterministic resource bounds, still need specification.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','full'])),notes=notes,checked_sources=[r['url'] for r in refs],state='improved_unfinished')
